neutralizer.quote:
do while (.not. (t>=t0 .and. t<t1))
   t0 = t1
   if (iU >0) u0 = u1
   if (iV >0) v0 = v1
   if (iZ >0) z0 = z1
   if (iW >0) w0 = w1
   if (idu >0) du0 = du1
   if (idv >0) dv0 = dv1
   call velocity_Boundary_read(t1,tmp,Unit_U,lVaru,lIsEof,nvar)
   t1 = t1+bcstarttime
   if (iU >0) u1 = tmp(:,iU-1)
   if (iV >0) v1 = tmp(:,iV-1)
   if (iZ >0) z1 = tmp(:,iZ-1)
   if (iW >0) w1 = tmp(:,iW-1)
   if (idu >0) du1 = tmp(:,idu-1)
   if (idv >0) dv1 = tmp(:,idv-1)
   if (lIsEof) exit !Exit on end of file condition
end do
